import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"子夏易传 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"子夏易传 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"zh/classics/zixia/031.md","filePath":"zh/classics/zixia/031.md"}'),i={name:"zh/classics/zixia/031.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>卦辞：習坎，有孚，維心亨。行有尚。</p><p>彖曰：習，坎重險也。水流而不盈，行險而不失其信，維心，亨。乃以剛中也行，有尚往有功也。天險不可升也，地險山川丘陵也。王公設險以守其國，險之時用大矣哉。</p><p>子夏：習，重也。水重至，流而不盈乎，兩坎也。為其嫌於止水也，故以習，坎名之。剛中而有孚，濬之斯流，流之斯止，浮之斯濟，沈之斯溺，不違於人，而人不可欺，不失信於，險也。夫行險而自能通者，固繫於心乎。能剛中志，果濟乎險而得其道者，則行險而有功也。天險絶其升也，地險山川丘陵也，天地猶險以成，而況於人乎。王公設城池以險國也，剛中藏用，以應險也。物之情而為險之用，非知者不能用，而終於正也。</p><p>象曰：水洊至習，坎。君子以常徳行習敎事。</p><p>子夏：水至柔而順，剛中而信，故能險而不滯也。雖洊流而至，其道一也。故君子以常行而存乎中習敎事，以禦其險，則得其正而有功也。</p><p>初六，習。坎入於坎窞凶。</p><p>象曰：習坎入坎，失道，凶也。</p><p>子夏：初柔而居重險之下，質弱而無心不知，濟險之道，習坎而入於坎窞，何以濟乎，故凶也。習重也，謂治其事也。</p><p>九二，坎有險，求小得。</p><p>象曰：求小得，未出中也。</p><p>子夏：居坎之内，前尚有險也。行險得中，而二柔附之體，險而有功也。雖求小得，未出險中也。</p><p>六三，來之坎，坎險且枕入於坎窞，勿用。</p><p>象曰：來之坎，坎終無功也。</p><p>子夏：位剛而以柔治，難矣。況兩坎之間乎。二剛，險也。而且枕之求可得乎。上坎之底，坎窞者也，之可得乎。進退莫可終，無功也。</p><p>六四，樽酒，簋貳，用缶，納約自牖，終无咎。</p><p>象曰：樽酒，簋貳，剛柔際也。</p><p>子夏：陰弱質也，附陽而濟居於上，體依五得位，濟其險矣。夫欲上之盡者，必自盡者也。誠之至，豈假於豐哉。則樽酒而簋，副器約而納寡，自至於牖以盡其忠，剛柔之際，承上之道也，終何咎矣。</p><p>九五，坎不盈，祇既平。无咎。</p><p>象曰：坎不盈，中未大也。</p><p>子夏：在坎中矣，坎豈盈乎。夫濟險者，盡斯泰乎。斯無咎矣。處其險，尊安而不慮，則險為咎矣，未至乎大，可無愼歟。</p><p>上六，繫用徽纆，寘于叢棘，三歲不得，凶。</p><p>象曰：上六失道，凶。</p><p>子夏：三歲也，柔而無心小人也。乘剛而履於極險，居於峻法之時，行極險之事，故用繫纆，索寘於叢棘，失其謀身之道也，以是三歲而凶。乃終。</p>',24)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
